"""One line of an invoice."""
from decimal import Decimal


class Line:
    def __init__(self, description, amount, quantity=1):
        if amount < 0:
            raise ValueError("an amount is never negative")
        self.description = description
        self.amount = amount
        self.quantity = quantity

    def value(self):
        return self.amount * self.quantity

    def __repr__(self):
        return f"Line({self.description!r}, {self.amount!r}, {self.quantity!r})"


def parse(text):
    """A Line from `description;amount;quantity`, as the teams' CSV exports write it."""
    description, amount, quantity = text.split(";")
    return Line(description, Decimal(amount), int(quantity))

