"""The tax on an amount, rounded to the cent."""
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


def tax(amount, rate):
    return (amount * rate).quantize(CENT, rounding=ROUND_HALF_UP)


def with_tax(amount, rate):
    return amount + tax(amount, rate)

