"""The totals of an invoice."""
from decimal import Decimal

from invoicer.tax import with_tax


def subtotal(lines):
    return sum((line.value() for line in lines), Decimal("0"))


def total(lines, rate):
    return with_tax(subtotal(lines), rate)

